(function() {
  try {
    function setInputValue(selector, value) {
      let el = document.querySelector(selector);
      if (!el) {
        const allElements = document.querySelectorAll('*');
        for (const parent of allElements) {
          if (parent.shadowRoot) {
            el = parent.shadowRoot.querySelector(selector);
            if (el) break;
          }
        }
      }
      if (el) {
        el.value = value;
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
        return true;
      }
      return false;
    }

    setInputValue('#field-name', 'Jane Smith');
    setInputValue('#field-address', '123 Test Lane');
    setInputValue('#field-city', 'Anytown');
    setInputValue('#field-zip', '00000');
    setInputValue('#field-card', '4111111111111111');
    setInputValue('#field-expiry', '12/28');
    setInputValue('#field-cvv', '123');

    let btn = document.querySelector('#place-order-btn');
    if (!btn) {
      const allElements = document.querySelectorAll('*');
      for (const parent of allElements) {
        if (parent.shadowRoot) {
          btn = parent.shadowRoot.querySelector('#place-order-btn');
          if (btn) break;
        }
      }
    }
    if (btn) {
      btn.click();
      return 'Success: Filled form and clicked place order';
    }
    return 'Error: Place order button not found';
  } catch(e) {
    return 'Error: ' + e.message;
  }
})()
